<div class="job-item-modal-backdrop" data-item-modal hidden><section class="job-start-modal"><h2>Add Part</h2><form method="post" action="index.php?page=admin&amp;section=jobcards-item-add"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="job_card_id" value="<?= (int)$job['id'] ?>"><input type="hidden" name="item_type" value="part"><input type="hidden" name="stock_item_id" data-modal-stock-id><label>Part Name<input class="form-control" name="item_name" data-modal-name readonly required></label><label>Quantity<input class="form-control" type="number" name="quantity" value="1" min="0.01" step="0.01" required></label><label>Unit Price<input class="form-control" type="number" name="unit_price" data-modal-price min="0" step="0.01"></label><div class="job-start-modal-actions"><button type="button" class="btn btn-light" data-item-close>Cancel</button><button class="btn btn-primary">Add Part</button></div></form></section></div>
<script>document.addEventListener('DOMContentLoaded',function(){const panel=document.querySelector('[data-stock-panel]'),search=document.querySelector('[data-stock-search]'),modal=document.querySelector('[data-item-modal]');if(!panel||!search||!modal)return;search.addEventListener('input',function(){const query=search.value.toLowerCase();panel.querySelectorAll('.stock-result').forEach(function(item){item.hidden=query!==''&&!item.textContent.toLowerCase().includes(query);});});panel.addEventListener('click',function(event){const item=event.target.closest('.stock-result');if(!item)return;modal.hidden=false;modal.querySelector('[data-modal-name]').value=item.dataset.name;modal.querySelector('[data-modal-price]').value=item.dataset.price;modal.querySelector('[data-modal-stock-id]').value=item.dataset.stockId;});modal.querySelector('[data-item-close]').addEventListener('click',function(){modal.hidden=true;});document.querySelector('[data-add-stock]')?.addEventListener('click',function(){search.focus();panel.scrollIntoView({behavior:'smooth',block:'center'});});});</script>
